private Frame _current = Frame.Empty;

Frame BuildNext() { /* fill the private back buffer */ return new Frame(); }

void Publish() {
    Frame finished = BuildNext();
    Interlocked.Exchange(ref _current, finished);   // atomic swap, old frame returned
}

Frame Snapshot() => Volatile.Read(ref _current);

